using Godot;
using System;
using System.Linq;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class WorldUiOperations
{
    private static void ModifyEntry(Control owner,string id,string collection,int index,Action<Settings> changed,string label)
    {var source=Source(owner,id);if(source==null)return;var next=new WorldSourceOperations().copy(source);var entries=next.Get(collection).AsGodotArray();if(index<0||index>=entries.Count)return;changed(entries[index].AsGodotDictionary());Apply(owner,id,next,label);}
    private static bool Exists(Control owner,string id)=>Session(owner).Get("document").As<Resource>().Call("component",id).AsGodotObject()!=null;
    public void connections(Control owner,Resource item,Resource source,Node parent,string[] types)
    {
        string id=item.Get("id").AsString();foreach(string field in new[]{"connect_settlements","connection_bridges"})Toggle(owner,parent,field=="connect_settlements"?"Connect settlements":"Allow bridges and approaches",source.Get(field).AsBool(),on=>Modify(owner,id,next=>next.Set(field,on),"Change settlement connections"));
        Choice(owner,parent,types,Math.Max(0,Array.IndexOf(types,source.Get("connection_road_type").AsString())),index=>Modify(owner,id,next=>next.Set("connection_road_type",types[index]),"Change connecting road type"));var records=Get(item.Get("parameters").AsGodotDictionary(),"world_connections",new GArray()).AsGodotArray();int selected=Math.Clamp(owner.GetMeta("world_connection_index",0).AsInt32(),0,Math.Max(0,records.Count-1));Choice(owner,parent,records.Select(value=>value.AsGodotDictionary()["name"].AsString()).ToArray(),selected,index=>{owner.SetMeta("world_connection_index",index);owner.Call("_refresh_properties");});if(records.Count==0)return;var record=records[selected].AsGodotDictionary();parent.AddChild(new Label {Text=record["length"].AsDouble().ToString("F0")+" m · "+record["bridges"].AsInt64()+" bridge(s)"});
        Button(owner,parent,"Make connection roads editable",()=>{var current=Source(owner,id);if(current==null)return;var next=new WorldConnectionOperations().make_editable(current,record);owner.SetMeta("world_section",1);owner.SetMeta("world_road_index",next.Get("roads").AsGodotArray().Count-1);Apply(owner,id,next,"Make connecting roads editable");});Button(owner,parent,"Disable this connection",()=>Modify(owner,id,next=>next.Get("connection_overrides").AsGodotDictionary()[record["id"]]=new Settings {["disabled"]=true},"Disable settlement connection"));
    }
    public void props(Control owner,string id,Resource source,Node parent)
    {
        var rules=source.Get("prop_rules").AsGodotArray();int index=Math.Clamp(owner.GetMeta("world_prop_index",0).AsInt32(),0,Math.Max(0,rules.Count-1));Choice(owner,parent,rules.Select(value=>value.AsGodotDictionary()["name"].AsString()).ToArray(),index,next=>{owner.SetMeta("world_prop_index",next);owner.Call("_refresh_properties");});if(rules.Count==0)return;var rule=rules[index].AsGodotDictionary();var modes=new[]{"Roadside","Region","Clusters","Grid"};
        Choice(owner,parent,new[]{"Along roads","Across region","In clusters","On grid"},Math.Max(0,Array.IndexOf(modes,rule["mode"].AsString())),next=>ModifyEntry(owner,id,"prop_rules",index,value=>value["mode"]=modes[next],"Change object placement mode"));
        foreach(var spec in new[]{("Spacing","spacing",.5,1000.0,.5),("Budget","budget",1.0,20000.0,1.0),("Rotation offset","yaw",-180.0,180.0,1.0)})Value(owner,parent,spec.Item1,Get(rule,spec.Item2,1.0).AsDouble(),spec.Item3,spec.Item4,spec.Item5,value=>ModifyEntry(owner,id,"prop_rules",index,next=>next[spec.Item2]=value,"Change object "+spec.Item2));
        if(rule["mode"].AsString()=="Roadside")
        {Toggle(owner,parent,"Place on sidewalks",Get(rule,"sidewalk",false).AsBool(),on=>ModifyEntry(owner,id,"prop_rules",index,next=>next["sidewalk"]=on,"Change sidewalk placement"));Value(owner,parent,"Distance from road",Get(rule,"setback",2.0).AsDouble(),.1,100,.1,value=>ModifyEntry(owner,id,"prop_rules",index,next=>next["setback"]=value,"Move roadside objects"));var sides=new[]{"Both","Left","Right"};Choice(owner,parent,sides,Math.Max(0,Array.IndexOf(sides,Get(rule,"sides","Both").AsString())),value=>ModifyEntry(owner,id,"prop_rules",index,next=>next["sides"]=sides[value],"Change road placement side"));}
        else Value(owner,parent,"Density",Get(rule,"density",.02).AsDouble(),0,10,.01,value=>ModifyEntry(owner,id,"prop_rules",index,next=>next["density"]=value,"Change object density"));
        string componentId=id+":props:"+rule["id"].AsString();Button(owner,parent,"Edit layer filters and palette",()=>Session(owner).Call("select",componentId)).Disabled=!Exists(owner,componentId);Button(owner,parent,"Remove placement rule",()=>Modify(owner,id,next=>{var values=next.Get("prop_rules").AsGodotArray();if(index<values.Count)values.RemoveAt(index);},"Remove object placement"));
    }
    public void forests(Control owner,string id,Resource source,Node parent,string[] layers)
    {
        var forests=source.Get("forests").AsGodotArray();int index=Math.Clamp(owner.GetMeta("world_forest_index",0).AsInt32(),0,Math.Max(0,forests.Count-1));Choice(owner,parent,forests.Select(value=>value.AsGodotDictionary()["name"].AsString()).ToArray(),index,next=>{owner.SetMeta("world_forest_index",next);owner.Call("_refresh_properties");});if(forests.Count==0)return;var forest=forests[index].AsGodotDictionary();Toggle(owner,parent,"Generate forest",Get(forest,"enabled",true).AsBool(),on=>ModifyEntry(owner,id,"forests",index,next=>next["enabled"]=on,"Toggle forest"));
        foreach(var spec in new[]{("Density","density",0.0,4.0,.05),("Clearing size","patch_scale",1.0,256.0,1.0),("Clearing variation","patch_strength",0.0,1.0,.05),("Instances per layer","budget",1.0,20000.0,1.0)})Value(owner,parent,spec.Item1,Get(forest,spec.Item2,1.0).AsDouble(),spec.Item3,spec.Item4,spec.Item5,value=>ModifyEntry(owner,id,"forests",index,next=>next[spec.Item2]=value,"Change forest "+spec.Item2));
        var labels=new[]{"Center X","Center Z","Width","Depth"};for(int axis=0;axis<4;axis++){int component=axis;var bounds=forest["bounds"].AsRect2();Value(owner,parent,labels[axis],axis<2?bounds.GetCenter()[axis]:bounds.Size[axis-2],axis>=2?1:-10000,16384,1,value=>ModifyEntry(owner,id,"forests",index,next=>{var rect=next["bounds"].AsRect2();var center=rect.GetCenter();if(component<2)center[component]=(float)value;else{var size=rect.Size;size[component-2]=(float)value;rect.Size=size;}rect.Position=center-rect.Size*.5f;next["bounds"]=rect;},"Resize forest region"));}
        parent.AddChild(new Label {Text="Vegetation layers"});for(int layer=0;layer<layers.Length;layer++){string layerId=id+":forest:"+forest["id"].AsString()+":"+layer;Button(owner,parent,"Edit "+layers[layer],()=>Session(owner).Call("select",layerId)).Disabled=!Exists(owner,layerId);}var row=new HBoxContainer();parent.AddChild(row);Button(owner,row,"⟳ Vary placement",()=>ModifyEntry(owner,id,"forests",index,next=>next["seed"]=next["seed"].AsInt64()+1,"Vary forest placement"));Button(owner,row,"Remove",()=>Modify(owner,id,next=>{var values=next.Get("forests").AsGodotArray();if(index<values.Count)values.RemoveAt(index);},"Remove forest"));
    }
    public void settlements(Control owner,string id,Resource source,Node parent)
    {
        var settlements=source.Get("settlements").AsGodotArray();int index=Math.Clamp(owner.GetMeta("world_settlement_index",settlements.Count-1).AsInt32(),0,Math.Max(0,settlements.Count-1));Choice(owner,parent,settlements.Select(value=>Get(value.AsGodotDictionary(),"name","Settlement").AsString()).ToArray(),index,next=>{owner.SetMeta("world_settlement_index",next);owner.Call("_refresh_properties");});if(settlements.Count==0)return;var settlement=settlements[index].AsGodotDictionary();Button(owner,parent,"Find suitable site",()=>{var job=new WorldSiteRequestJob();owner.AddChild(job);job.start(owner,id,index,"Town");}).Disabled=source.Get("terrain_id").AsString().Length==0;bool roadNetwork=Get(settlement,"layout_mode","Grid").AsString()=="Road network";
        Choice(owner,parent,new[]{"Generate streets and blocks","Use drawn road network"},roadNetwork?1:0,value=>ModifyEntry(owner,id,"settlements",index,next=>next["layout_mode"]=value==1?"Road network":"Grid","Change settlement road layout"));if(roadNetwork)Value(owner,parent,"Frontage lot size",Get(settlement,"lot_size",18.0).AsDouble(),10,64,1,value=>ModifyEntry(owner,id,"settlements",index,next=>next["lot_size"]=value,"Resize road-frontage lots"));
        foreach(int axis in new[]{0,2})Value(owner,parent,"Center "+new[]{"X","Y","Z"}[axis],settlement["center"].AsVector3()[axis],-10000,10000,1,value=>ModifyEntry(owner,id,"settlements",index,next=>{var center=next["center"].AsVector3();center[axis]=(float)value;next["center"]=center;},"Move settlement"));
        foreach(var spec in new[]{("Radius","radius",8.0,512.0,1.0),("Blocks per side","blocks",1.0,6.0,1.0),("Minimum floors","height_min",1.0,8.0,1.0),("Maximum floors","height_max",1.0,8.0,1.0),("Setback","setback",1.0,10.0,.25)}){if(spec.Item2=="blocks"&&(settlement["profile"].AsString()=="Village"||roadNetwork))continue;Value(owner,parent,spec.Item1,Get(settlement,spec.Item2,1.0).AsDouble(),spec.Item3,spec.Item4,spec.Item5,value=>ModifyEntry(owner,id,"settlements",index,next=>next[spec.Item2]=value,"Change settlement"));}
        Button(owner,parent,"⟳ New settlement variation",()=>ModifyEntry(owner,id,"settlements",index,next=>next["seed"]=Get(next,"seed",1).AsInt64()+1,"Vary settlement"));Button(owner,parent,"Remove settlement",()=>Modify(owner,id,next=>{var values=next.Get("settlements").AsGodotArray();if(index<values.Count)values.RemoveAt(index);},"Remove settlement"));
    }
}
